// Trafikljusregel: bestämmer vilken lampa som ska lysa.
//   Ej larmat:  grön = lugnt, gul = rörelse nyligen
//   Larmat:     grön = lugnt, röd = rörelse upptäckt (gul under utgångsfördröjningen)
// Tar emot meddelanden märkta msg.topic = "motion", "armed" eller "tick".
const HOLD_ALARM_S = 60;       // röd lyser så här länge efter sista rörelsen
const HOLD_ACTIVITY_S = 120;   // gul lyser så här länge efter sista rörelsen
const ARM_DELAY_S = 30;        // tid att gå ut efter att larmet slagits på
const STALE_S = 180;           // "rörelse pågår" gäller bara om PIR hörts av nyligen
const RESYNC_S = 60;           // skicka alla lampors läge igen, ifall Pi:n startat om

const now = Date.now();
const raw = (msg.payload !== null && typeof msg.payload === "object") ? msg.payload.value : msg.payload;
const num = (raw === null || raw === undefined || raw === "") ? NaN : Number(raw);

if (msg.topic === "motion" && !isNaN(num)) {
    const wasMoving = context.get("motion") === true;
    context.set("motion", num !== 0);
    context.set("motionMsgAt", now);
    if (num !== 0 || wasMoving) context.set("lastMotion", now);   // tiden räknas från rörelsens slut
} else if (msg.topic === "armed" && !isNaN(num)) {
    const wasArmed = context.get("armed") === true;
    context.set("armed", num !== 0);
    if (num !== 0 && !wasArmed) context.set("armedAt", now);
} else if (msg.topic !== "tick") {
    return null;
}

const armed = context.get("armed") === true;
const armedAt = context.get("armedAt") || 0;
const lastMotion = context.get("lastMotion");
const seenAt = context.get("motionMsgAt");
let moving = context.get("motion") === true && seenAt !== undefined && now - seenAt < STALE_S * 1000;
let age = lastMotion === undefined ? Infinity : (now - lastMotion) / 1000;

let want;
if (armed) {
    const guardFrom = armedAt + ARM_DELAY_S * 1000;
    if (now < guardFrom) {
        want = "yellow";                                  // utgångsfördröjning
    } else {
        if (lastMotion !== undefined && lastMotion < guardFrom) age = Infinity;  // ignorera rörelse före bevakning
        want = (moving || age < HOLD_ALARM_S) ? "red" : "green";
    }
} else {
    want = (moving || age < HOLD_ACTIVITY_S) ? "yellow" : "green";
}

const out = [null, null, null, null];
const prev = context.get("sent") || {};
const resync = now - (context.get("syncAt") || 0) >= RESYNC_S * 1000;
const sent = {};
["red", "yellow", "green"].forEach((color, i) => {
    const v = color === want ? 1 : 0;
    sent[color] = v;
    if (resync || prev[color] !== v) out[i] = { payload: v, color: color };
});
context.set("sent", sent);
if (resync) context.set("syncAt", now);

if (want === "red" && context.get("want") !== "red") {
    out[3] = { payload: "Larm: rörelse upptäckt medan larmet är påslaget.", warning: true };
}
context.set("want", want);

node.status({ fill: want === "red" ? "red" : want === "yellow" ? "yellow" : "green", shape: "dot",
              text: (armed ? "larmat" : "ej larmat") + " → " + want });
return out;

// Regel: mycket aktivitet. Larmar när antalet rörelser senaste 10 minuterna når 5,
// och avlarmar först när det är nere på 2 (hysteres, så att larmet inte fladdrar).
const WINDOW_S = 600;
const WARN_AT = 5;
const CLEAR_BELOW = 2;

const now = Date.now();
const raw = (msg.payload !== null && typeof msg.payload === "object") ? msg.payload.value : msg.payload;
const v = (raw === null || raw === undefined || raw === "") ? NaN : Number(raw);
if (isNaN(v)) return null;

const prevHigh = context.get("high") === true;
let edges = context.get("edges") || [];
if (v !== 0 && !prevHigh) edges.push(now);           // ny rörelse = stigande flank
context.set("high", v !== 0);
edges = edges.filter(t => now - t < WINDOW_S * 1000);
context.set("edges", edges);

const n = edges.length;
const busy = context.get("busy") === true;
node.status({ text: n + " rörelser/10 min" });
if (!busy && n >= WARN_AT) {
    context.set("busy", true);
    return { payload: "Mycket aktivitet: " + n + " rörelser senaste 10 minuterna.", warning: true };
}
if (busy && n < CLEAR_BELOW) {
    context.set("busy", false);
    return { payload: "Aktiviteten har lugnat sig (" + n + " rörelser senaste 10 minuterna).", warning: false };
}
return null;
